{
  "schema_version": 1,
  "task": {
    "problem_id": "space-diving-descent",
    "description": "A skydiver (total mass 190 kg: suit + parachute) is carried by a rocket above the atmosphere and then descends to Earth's surface. Analyze the challenges/dangers of the descent and find the maximum altitude from which a safe descent is possible.",
    "target_quantity": "maximum safe descent altitude (km), with the governing velocity and deceleration profiles that define the safety boundary",
    "safety_constraints_ref": "space_diving_params.json#safety_constraints (5 g sustained <= 5 s; peak 10 g <= 0.1 s; mass 190 kg)"
  },
  "stage": "node_1_spec",
  "quota": {
    "downstream_retries_remaining": 3,
    "note": "Decrement once per code-edit + re-run cycle inside node_2b_modeling; at 0 with no convergence, trigger annealing rollback to hypothesis_layer."
  },
  "hypothesis_layer": {
    "model_form": "vertical descent ODE in u = v^2/2 vs fallen distance: du/dx = g_eff(z) - (rho(z)*CD*Mach-regime*A_Mach/(2*m))*u, z = z0 - x, with piecewise CD/A by Mach band and altitude-dependent sound speed for the Mach banding",
    "assumptions": {
      "drag_regime_partition": "three regimes keyed to local Mach M = v/a_sound(z): subsonic M<=0.8, transonic 0.8<M<1.2, supersonic M>=1.2; Mach band thresholds 0.8/1.2 are template-candidates to be re-checked against this problem's transonic physics (transonic drag-rise band depends on local sound speed, which at 100-150 km is ~305-320 K, a ~ 348-358 m/s — to be quantified in node_2a adaptation notes)",
      "CD_subsonic": 1.0,
      "CD_transonic": 5.0,
      "A_subsonic_m2": 0.18,
      "A_supersonic_m2": 0.2,
      "mass_kg": 190,
      "g_model": "GM/(R+z)^2 with GM=3.986004418e14 m^3/s^2, R=6.371e6 m; drag at Mach > ~2 neglected (no free-molecular regime); linear-interp density on a 1-2 km grid"
    },
    "last_known_good_version": null
  },
  "dimensional_table": {},
  "knowledge_routing": {
    "matched_template": null,
    "param_json": null,
    "routing_decision_audit": null
  },
  "data_source_decision": {
    "atmosphere_source": null,
    "verification_baseline": null,
    "rationale": null,
    "availability_check": null,
    "manual_fetch_guide": null,
    "user_choice": null,
    "note": "Only Node 1.5 writes this; downstream data-source fallbacks must surface as an anomaly, not by editing this in place."
  },
  "numerical_artifacts": {},
  "audit_logs": [],
  "anomalies": [],
  "verification": {
    "benchmark_source": null,
    "comparison_result": null,
    "max_relative_error": null
  },
  "report": {
    "conclusion": null,
    "traceability": {}
  }
}

